import pathlib,json,hashlib,datetime,html
P=pathlib.Path(__file__).resolve().parents[1];RUN=P/'runs/C8_FROZEN_IMAGENET_RGB_TWO_SCALE'
H=lambda f:hashlib.sha256(f.read_bytes()).hexdigest()
def bind(f):return {'path':str(f.resolve()),'sha256':H(f),'bytes':f.stat().st_size}
def read(f):return json.loads(f.read_text())
def pct(x):return f'{100*x:.1f}%'
def ratio(n,d):return f'{n}/{d} ({pct(n/d)})'
def put(f,x):assert not f.exists(),str(f);f.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
