adm=read(P/'ROOT_SOURCE_ADMISSION.json');source=read(RUN/'SOURCE_RESULTS.json');design=read(P/'ROOT_C8_DESIGN_BEFORE_FEATURE_FORWARD.json');fit=read(RUN/'FIT_COMPLETE.json');cases=read(P/'saved_failure_views/CASES.json')
assert fit['completed'] and fit['selected_update']==source['selected_update']==adm['selected_update']==300
