labels={'v61':'v61','C1_frozen_reference':'C1 저장 기준','C6_RAW':'C6 raw 잔차','C7_CLIP2':'C7 clip2 잔차','C8_RGB':'C8 frozen RGB'}
for key in ['v61','C1_frozen_reference','C6_RAW','C7_CLIP2','C8_RGB']:
 v=c[key]['VALIDATION'];row={'model':key,'display':labels[key],'old_public_D_E':v['old_real'],'old_cover_E':v['eight_cohorts']['old_COVER_E'],'old_sham_D':v['eight_cohorts']['old_SHAM_D'],'old_triple':v['old_matched_triplets'],'new_synthetic_D_E':v['new_synthetic'],'new_triple':v['new_matched_triplets']};comparison.append(row)
proofs={k:bind(f) for k,f in {'design':P/'ROOT_C8_DESIGN_BEFORE_FEATURE_FORWARD.json','fit_complete':RUN/'FIT_COMPLETE.json','source_results':RUN/'SOURCE_RESULTS.json','source_gate_results':RUN/'SOURCE_GATE_RESULTS.json','source_admission':P/'ROOT_SOURCE_ADMISSION.json','saved_source_review':reviewfile,'saved_case_selection':P/'saved_failure_views/CASES.json'}.items()}
for im in cases['images']:
 f=pathlib.Path(im['path']);assert H(f)==im['sha256']
v104=P.parent/'query_visibility_public_flat_pallet_queries_20261023_v104/visual_query_review/ACTUAL_VISUAL_READOUT_KO.html'
result={'completed':True,'UTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'candidate':'C8_FROZEN_IMAGENET_RGB_TWO_SCALE','main_outcome_KO':'합성 외부 cover 제어는 크게 개선됐으나 공개 RGB 기반 controlled cover 일반화는 부족하다. 12개 사전 gate 중9개만 통과해 불채택하며 새 current223 추론은 없다.','architecture':{'frozen_encoder':'ResNet18 ImageNet1K_V1','scales':'unchanged RGB96 and its central32; each resized224','trainable_head_parameters':65793,'P3_or_C1_score_input':False,'new_coordinates_predicted':False},'selected_update':300,'optimizer_updates':2000,'selected_criterion_eight_VAL_BCE':source['criterion_eight_VAL_cohorts_BCE'],'source_gates':r['source_gates'],'admitted':False,'passed_gates':9,'failed_gates':3,'main_source_comparison':comparison,'C8_old_PUBLIC_TRAIN_triples':c['C8_RGB']['TRAIN']['old_matched_triplets'],'C8_old_PUBLIC_VAL_triples':c['C8_RGB']['VALIDATION']['old_matched_triplets'],'C8_new_SYNTH_VAL_triples':c['C8_RGB']['VALIDATION']['new_matched_triplets'],'C8_VAL_eight_cohorts':oc,'denominator_and_semantic_boundary':{'all_occurrences':33984,'D':1215,'E':303,'S_excluded':396,'GT_U':32070,'factual_input_U_allrows':r['factual_U'],'known_VAL_U_rate_old':old['known_U_rate'],'known_VAL_U_rate_new':new['known_U_rate'],'labels':'Conditional physical-cue AUX; native identity UNKNOWN; not human gold or current metrics. Geometric S outside learned D/E, not recoded to E or teacher U.','old_controls':'Public RGB with GT-guided real-donor opaque-cover/sham edits;119 VAL ranks cluster18 base queries9images. Not119 natural occlusion events. Natural BEFORE_E VAL only2.','new_controls':'Simplified synthetic expected-cue RGB composites. Camera/aspect/material tests are source controls, not real deployment evidence.','development':'Repeated source VAL development; not a blind test.','new_V104_pilot_rows_used_in_C8':0},'audit_scope':'Saved source metadata/GT/decoding/selector/sampler/metrics reconciliation PASS; does not certify visual label truth, feature internals or independent generalization.','fixed_source_figures':cases,'interpretation_limits_KO':['중앙 crop에 donor가 크게 보여도 공개 VAL 첫 cover 실패에서 D였다. 한 그림으로 실패 원인이나 특정 encoder의 한계를 단정하지 않는다.','C8은 합성 D 보존과 triple 성능을 개선했지만 공개 controlled triple은 C7보다 낮다. 단일 수치로 전체 우월을 주장하지 않는다.','실제 초기 query의 target/cue 대응은 별도 문제다. V104에서 multi-pallet box, floor·사람·트럭 위 q가 관찰됐고 자동 E/위치 오답 gold를 만들지 않았다.'], 'next_KO':'더 다양한 자연 실제 RGB에서 고정 초기 q/L의 target↔물리 cue·좌표 불확실성·외부 blocker 근거를 독립적으로 정리하고, target-context 표현을 검토한다. 임의 threshold/LR 재추첨이나 현재자료 선택으로 해결하지 않는다.','new_current_inference':0,'report_model_or_feature_forward':0,'report_fit_or_PnP':0,'current_training_threshold_checkpoint_selection':0,'proofs':proofs,'V104_query_ambiguity_readout':bind(v104)}
put(P/'ROOT_RESULTS_KO.json',result)
metricrows=''
for label,m in [('공개 RGB 기반 AUX VAL',old),('합성 expected-cue AUX VAL',new)]:
 mat=m['matrix'];d=sum(mat[0]);e=sum(mat[1]);metricrows+=f'<tr><td>{label}</td><td>{ratio(mat[0][0],d)}</td><td>{ratio(mat[1][1],e)}</td><td>{pct(m["D_precision"])}</td><td>{pct(m["E_precision"])}</td><td>{pct(m["known_U_rate"])}</td></tr>'
comprows=''
for row in comparison:
 n=row['new_synthetic_D_E']['matrix'];d=sum(n[0]);e=sum(n[1]);p=row['old_triple'];np=row['new_triple'];comprows+=f'<tr class="{"c8" if row["model"]=="C8_RGB" else ""}"><td>{row["display"]}</td><td>{row["old_cover_E"]["correct"]}/119</td><td>{row["old_sham_D"]["correct"]}/119</td><td>{p["correct"]}/119</td><td>{n[0][0]}/{d}</td><td>{n[1][1]}/{e}</td><td>{np["correct"]}/32</td></tr>'
failedrows=''
for k,v in adm['failed_gates'].items():
 name={'old_natural_before_E_recall_min':'공개 자연 BEFORE E','old_cover_E_recall_min':'공개 controlled COVER E','old_accepted_VAL_pair_all3_min':'공개 BEFORE/COVER/SHAM 모두 정답'}[k]
 failedrows+=f'<tr><td>{name}</td><td>{pct(v["value"])}</td><td>≥ {pct(v["limit"])}</td></tr>'
rel104='../query_visibility_public_flat_pallet_queries_20261023_v104/visual_query_review/ACTUAL_VISUAL_READOUT_KO.html'
doc='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>C8: 합성 cover 개선, 공개 RGB 일반화 미달</title><style>body{font:17px/1.6 NanumGothic,sans-serif;max-width:1120px;margin:36px auto;padding:0 22px;color:#1c2937;background:#fff}h1{font-size:29px;line-height:1.4;margin-bottom:12px}h2{font-size:23px;margin-top:34px}p{margin:13px 0}.lead{font-size:19px;background:#f5f7fa;border-left:4px solid #bb4b30;padding:15px 18px}.tag{display:inline-block;border:1px solid #d0d8e1;background:#f3f6f9;padding:5px 10px;margin:0 7px 6px 0;border-radius:4px}table{border-collapse:collapse;width:100%;font-size:15px;line-height:1.5;margin:16px 0}td,th{border-bottom:1px solid #d7dfe7;text-align:right;padding:9px 7px}td:first-child,th:first-child{text-align:left}th{background:#f3f6f9}.c8{background:#edf6ff;font-weight:bold}a{color:#155da2}small,.small{color:#536272;font-size:14px}.plots{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start}.plots img{display:block;width:100%;height:auto}figure{margin:0}figcaption{font-size:14px;line-height:1.5;margin:10px 0}ul{padding-left:22px}footer{border-top:1px solid #d7dfe7;margin-top:32px;padding-top:14px;font-size:14px;color:#536272}@media(max-width:800px){body{font-size:16px;padding:0 12px}.plots{grid-template-columns:1fr}table{font-size:12px}td,th{padding:7px 3px}}</style><h1>C8: 합성 외부 cover는 개선됐지만, 공개 RGB 전이는 미달</h1><p class="lead"><b>9/12 gate 통과 → 불채택.</b> 합성 VAL은 D205/209·E34/34, matched triple30/32였다. 공개 RGB 기반 controlled cover는56/119, triple46/119에 그쳐 새 current223 추론은 하지 않았다.</p><div><span class="tag">선택 step300 / 2000</span><span class="tag">frozen ImageNet RGB + head65,793</span><span class="tag">원 q/L 유지 · 좌표 보정 없음</span></div><p>ResNet18의 고정 ImageNet 특징으로 RGB96 전체와 중앙32를 읽고 작은 binary head만 학습했다. P3나 C1 logit은 입력하지 않았다. 결과는 <b>조건부 물리 cue AUX</b>이며 human/native8 gold나 current 성능이 아니다.</p><h2>실제 source VAL 결과</h2><table><tr><th>대상</th><th>D 재현율</th><th>E 재현율</th><th>D 정밀도</th><th>E 정밀도</th><th>known U</th></tr>'''+metricrows+'''</table><p>공개 E57/121은 자연 BEFORE1/2와 controlled COVER56/119의 합이다. Sham D는108/119였다. 공개 triple은 TRAIN67/75(89.3%) → VAL46/119(38.7%)로 벌어졌다. 합성 triple은30/32(93.8%)였다.</p><table><tr><th>실패한 사전 gate</th><th>실제</th><th>기준</th></tr>'''+failedrows+'''</table><h2>같은 source 입력에서의 저장 비교</h2><p class="small">각 arm의 이미 동결된 저장 결과를 같은 행에서 비교했다. 아래 표로 checkpoint를 다시 고르지 않았다. Triple은 동일 BEFORE·COVER·SHAM 세 응답이 모두 맞은 수다.</p><table><tr><th>고정 모델</th><th>공개 cover E</th><th>공개 sham D</th><th>공개 triple</th><th>합성 D</th><th>합성 E</th><th>합성 triple</th></tr>'''+comprows+'''</table><p class="small">C1은 이미 저장된 frozen reference component이며 새 C1 추론이 아니다. v61은 원 presence≥0을D로, 나머지는 external logit≥0을E로 읽는 기존 tie 규칙을 유지했다. C8은 합성 성능을 개선했지만 공개 triple은 C7보다 낮아 전체 우월을 주장할 수 없다.</p><h2>실제 저장 crop: 전체96과 중앙32</h2><p>동결된 C8 출력에서 진단 조건에 맞는 첫 canonical 사례를 표시했다. 같은 쌍의 q/L은 동일하고, 이 사후 그림은 학습 행·threshold·checkpoint를 바꾸지 않는다. 공개 VAL 첫 실패는 중앙에 donor가 크게 들어와도 D를 유지한다. 그림만으로 실패 원인을 확정하지 않는다.</p><div class="plots"><figure><img src="saved_failure_views/SOURCE_CONTROLS_RGB96.png" alt="C8 동일 qL 전체 RGB96 저장 source controls" loading="eager"><figcaption>원 RGB96. 공개 TRAIN 성공 / 공개 VAL cover 실패 / 공개 VAL 성공 / 합성 VAL 성공 순서.</figcaption></figure><figure><img src="saved_failure_views/SOURCE_CONTROLS_CENTRAL32.png" alt="C8 동일 qL 중앙32 저장 source controls" loading="eager"><figcaption>같은 사례의 중앙32. 단순 합성 RGB와 공개 RGB 기반 donor 편집은 실제 배포 외부가림과 동일한 증거가 아니다.</figcaption></figure></div><h2>한계와 다음 source 작업</h2><p>전체33,984행을 유지했다. D1,215·E303만 binary 학습 대상이고, geometric S396은 이 과제 밖으로 분리했다. teacher U32,070과 factual input U4,686은 별개다. 공개119개 VAL 제어쌍은18개 base query·9개 이미지에 모여 있으며 자연 E VAL은2개뿐이다. 반복 사용한 source VAL은 blind test가 아니다.</p><p>현재의 초기 q가 올바른 물리 cue에 대응하는지는 별도 문제다. <a href="'''+rel104+'''">V104 실제32 query 검토</a>에서는 여러 pallet을 감싼 box와 floor·사람·트럭 위 q가 관찰됐다. 다른 물체가 보인다는 사실만으로 E나 위치 오답 gold를 만들지 않았다. V104 새 표본은 C8 학습에 쓰지 않았다.</p><p><b>다음은 더 넓은 자연 실제 RGB에서 target↔물리 cue·불확실성·외부 blocker 근거를 독립적으로 연결하는 일이다.</b> 고정 q/L을 유지하며 target-context 표현을 검토한다. 임의 threshold/LR 재추첨으로 현재 실패를 덮지 않는다.</p><footer><a href="ROOT_RESULTS_KO.json">정량·12개 gate·binding JSON</a> · <a href="ROOT_SOURCE_ADMISSION.json">root 불채택 결정</a> · <a href="saved_source_review/REVIEW.json">저장 결과 독립 검토</a> · <a href="runs/C8_FROZEN_IMAGENET_RGB_TWO_SCALE/SOURCE_RESULTS.json">원 source 결과</a><p>저장 검산 PASS는 행·수치·선택 절차가 일치한다는 뜻이며 의미 라벨이나 일반화의 인증이 아니다. 이 보고서 작성에서 새 모델/특징/학습/current223/PnP 실행0. 모든 판정과 gate는 동결된 원 결과를 유지했다.</p></footer></html>'''
f=P/'ROOT_READOUT_KO.html';assert not f.exists();f.write_text(doc)
put(P/'report_preparation/REPORT_BUILD_RECEIPT.json',{'completed':True,'builder':bind(pathlib.Path(__file__).resolve()),'result':bind(P/'ROOT_RESULTS_KO.json'),'HTML':bind(f),'bindings':proofs,'images':[bind(pathlib.Path(im['path'])) for im in cases['images']],'saved_only':True,'new_model_fit_current_PnP':0})
for n in ['ROOT_READOUT_KO.html','ROOT_RESULTS_KO.json','report_preparation/REPORT_BUILD_RECEIPT.json']:print(n,H(P/n))
